#include "model_render_inputs_candidate.h"
#include "model_body_selection_candidate.h"
#include <iostream>
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("model base required");std::string base=argv[1];auto read=[](const std::string&p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("asset missing");return std::vector<uint8_t>((std::istreambuf_iterator<char>(f)),{});};auto model=readSfmModelGeometryCandidate(read(base+".mdl"),read(base+".vvd"),read(base+".dx90.vtx"));auto mount=std::filesystem::path(base).parent_path();while(!mount.empty()&&mount.filename()!="models")mount=mount.parent_path();if(mount.empty())throw std::runtime_error("mount missing");size_t cases=0;for(size_t skin=0;skin<model.materials.skins.size();++skin){auto inputs=prepareModelRenderInputsCandidate(model,skin,{mount.parent_path()},2,modelBodySelectionCandidate(0,model.bodyModelCounts,model.bodyBases));std::cout<<"skin="<<skin<<" triangles="<<inputs.indices.size()/3<<" materials="<<inputs.materials.size()<<'\n';for(auto&range:inputs.ranges)if(range.eyeball>=0)std::cout<<"eye_draw_binding mesh="<<range.mesh<<" record="<<range.eyeball<<" material="<<range.materialIndex<<"\n";for(auto&material:inputs.materials)if(!material.source.irisTexture.empty())std::cout<<"iris_resource="<<material.source.irisTexture.string()<<" shader="<<material.source.syntax.key<<" native_eye_shader=unfinished\n";++cases;}for(size_t group=0;group<model.bodyModelCounts.size();++group)for(uint32_t part=1;part<model.bodyModelCounts[group];++part){auto choices=modelBodySelectionCandidate(0,model.bodyModelCounts,model.bodyBases);choices[group]=part;auto inputs=prepareModelRenderInputsCandidate(model,0,{mount.parent_path()},2,choices);std::cout<<"body_group="<<group<<" part="<<part<<" triangles="<<inputs.indices.size()/3<<" materials="<<inputs.materials.size()<<'\n';++cases;}std::cout<<"alternate render inputs passed cases="<<cases<<" native_visual_parity=unverified\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
